command:
candidate=/tmp/antrieb-backend.conf
cat > "$candidate" <<ANTRIEB_NGINX_EOF
server {
    listen 5660 default_server;
    server_name _;

    location = / {
        default_type text/plain;
        return 200 "$NODE_NAME\\n";
    }

    location / {
        return 404;
    }
}
ANTRIEB_NGINX_EOF
if [ "$(id -u)" -eq 0 ]; then
  install -o root -g root -m 0644 "$candidate" /etc/nginx/conf.d/antrieb-backend.conf
  nginx -t || exit 1
  systemctl enable nginx
  systemctl restart nginx
else
  sudo -n install -o root -g root -m 0644 "$candidate" /etc/nginx/conf.d/antrieb-backend.conf
  sudo -n nginx -t || exit 1
  sudo -n systemctl enable nginx
  sudo -n systemctl restart nginx
fi
printf 'active='
systemctl is-active nginx
printf 'enabled='
systemctl is-enabled nginx
ss -tlnp | awk 'NR == 1 || $4 ~ /:5660$/'
printf 'response='
curl --fail --silent --show-error --max-time 3 "http://$NODE_IP:5660/"

